# owner: platform
"""Seating plans: students dealt into rows by last name."""

from typing import Iterable, List

from rosterkit.models import Student

def seating_rows(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    ordered = sorted(students, key=last_name_of)
    if seats_per_row <= 0 or not ordered:
        raise ValueError("bad seats or no students")
    return format_rows(chunk(ordered, seats_per_row))

def last_name_of(student: Student) -> str:
    """Sort key for the seating order."""
    return student.last_name

def chunk(
    ordered: List[Student], seats_per_row: int
) -> List[List[Student]]:
    """Cut a sorted list into rows of seats_per_row."""
    return [
        ordered[start:start + seats_per_row]
        for start in range(0, len(ordered), seats_per_row)
    ]

def format_rows(groups: List[List[Student]]) -> List[str]:
    """Number each group and join its names with bars."""
    rows = []
    for number, group in enumerate(groups, 1):
        people = [item.display_name for item in group]
        rows.append(f"Row {number}: " + " | ".join(people))
    return rows

