# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

def make_student(last_name: str, first_name: str):
    return Student("0", last_name, first_name, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Varrow", "Ines")
        ]

    def test_sorted_by_last_name_then_chunked(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Varrow, Ines"
            ]
        )

    def test_exact_fit_has_one_row(self):
        rows = seating_rows(self.students, 3)
        self.assertEqual(len(rows), 1)
        self.assertIn("Varrow, Ines", rows[0])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
